/* Snippet: Design system docs — generated by sitereal. */
/* design-system.html only: renders token specimens from the live custom properties (tokens.css). */
(() => {
  const root = document.documentElement;
  const val = (name) => getComputedStyle(root).getPropertyValue(`--${name}`).trim();
  /* clamp(16px, calc(…), 20px) → "16 → 20px" */
  const short = (v) => { const m = v.match(/^clamp\((\d+(?:\.\d+)?)px,.*,\s*(\d+(?:\.\d+)?)px\)$/); return m ? `${m[1]} → ${m[2]}px` : v; };
  const names = (el, attr) => el.getAttribute(attr).split(/\s+/).filter(Boolean);
  const el = (tag, cls, text) => { const n = document.createElement(tag); n.className = cls; if (text != null) n.textContent = text; return n; };

  document.querySelectorAll('[data-ds-swatches]').forEach((grid) => names(grid, 'data-ds-swatches').forEach((n) => {
    const card = el('div', 'w-ds-swatch');
    const chip = el('div', 'w-ds-swatch__chip'); chip.style.background = `var(--${n})`;
    const meta = el('div', 'w-ds-swatch__meta');
    const value = el('span', 'w-ds-swatch__value', val(n)); value.dataset.dsToken = n;
    meta.append(el('span', 'w-ds-swatch__name', `--${n}`), value);
    card.append(chip, meta); grid.append(card);
  }));

  document.querySelectorAll('[data-ds-scale]').forEach((list) => names(list, 'data-ds-scale').forEach((n) => {
    const row = el('div', 'w-ds-scale__row');
    const bar = el('span', 'w-ds-scale__bar'); bar.style.width = `calc(var(--${n}) * 3)`;
    row.append(el('span', '', `--${n}`), el('span', '', short(val(n))), bar); list.append(row);
  }));

  const tiles = (attr, apply) => document.querySelectorAll(`[${attr}]`).forEach((grid) => names(grid, attr).forEach((n) => {
    const t = el('div', 'w-ds-tile'); apply(t, n);
    t.append(el('span', 'w-ds-tile__name', `--${n}`), el('span', '', val(n).length > 60 ? val(n).slice(0, 60) + '…' : val(n)));
    grid.append(t);
  }));
  tiles('data-ds-radius', (t, n) => { t.style.borderRadius = `var(--${n})`; });
  tiles('data-ds-shadow', (t, n) => { t.style.border = '0'; t.style.borderRadius = 'var(--radius-l)'; t.style.boxShadow = `var(--${n})`; });
  tiles('data-ds-stroke', (t, n) => { t.style.border = `var(--${n})`; });

  document.querySelectorAll('[data-ds-motion]').forEach((table) => names(table, 'data-ds-motion').forEach((n) => {
    const row = el('div', 'w-ds-table__row');
    row.append(el('p', 'w-ds-table__meta', `--${n}`), el('p', 'w-text-m', val(n)), el('p', 'w-ds-table__meta', 'Variables › Motion'));
    table.append(row);
  }));

  /* swatch values follow the light / dark switch */
  new MutationObserver(() => document.querySelectorAll('[data-ds-token]').forEach((v) => { v.textContent = val(v.dataset.dsToken); }))
    .observe(root, { attributes: true, attributeFilter: ['data-brx-theme'] });
})();
